//! What the C render pool (`driver/src/pvr_render_pool.h` at 5398fb14,
//! sha256 1a11e8812917134ee0a800e5e89a1deb9ad2f4bc2a7e9a6a3570673ce6d89d2a) did in one deterministic
//! sequence: 2769 operations over the three heaps (random allocations and
//! frees with rollback on some, a full table and the overflow chain, three
//! double frees, a chain header overwritten while free, frees the pool
//! cannot take back, a refused request, everything freed and merged). Test
//! data for `tests.rs`; do not edit.
//!
//! Each row: the operation (`A` alloc: heap, size; `F` free: block index in
//! allocation order, size, flags 1 rollback / 2 no CPU mapping / 4 no heap's
//! address; `P` overwrite a chain header: heap, position), then the return
//! code, heap offset and carveout offset of an allocation, then after the
//! operation the physical cursor, the three device-VA cursors, the three
//! chain lengths, KiB dropped, double frees, bad chain headers and KiB rolled
//! back.
//!
//! Made by the program below, with the header beside it
//! (`git show 5398fb14:driver/src/pvr_render_pool.h`):
//! `cc -std=gnu11 -O1 -Wall -Wextra -Werror -I. gen.c -o gen && ./gen` (rows sha256
//! 171023b71204639ec03596ea4ccc174d79e7ebd885ca065cc44fcd5553cd2456).
//!
//! ```text
//! /* SPDX-License-Identifier: Apache-2.0 */
//! /* The golden trace of the C render pool (driver/src/pvr_render_pool.h at
//!  * 5398fb14), for driver/rust/src/gpu/pvr/pool's replay test. The bump and
//!  * the rollback are modelled as gpu::pvr::mem's bo_alloc and bo_rollback do
//!  * them: one physical cursor shared by the three heaps, a device-VA cursor
//!  * per heap, both page rounded. The carveout: 32 MiB, the pool from 1 MiB
//!  * (the Rust replay's rig).
//!  *   cc -std=gnu11 -O1 -Wall -Wextra -Werror -I. gen.c -o gen && ./gen > rows
//!  */
//! #include <errno.h> /* ENOMEM */
//! #include <stdbool.h>
//! #include <stdint.h>
//! #include <stdio.h>
//! #include <stdlib.h>
//! #include <string.h>
//!
//! enum pvr_render_heap { PVR_RENDER_HEAP_GENERAL = 0, PVR_RENDER_HEAP_PDS, PVR_RENDER_HEAP_USC };
//! struct pvr_gpu_bo { uint64_t gpu; uint8_t *cpu; uint32_t heap_off; };
//!
//! #define ROUND_UP(x, a) (((x) + ((a) - 1)) & ~((__typeof__(x))(a) - 1))
//! #define LOG_WRN(...) do { } while (0)
//! static void sys_cache_data_flush_range(void *p, size_t n) { (void)p; (void)n; }
//!
//! #define CARVEOUT (32u << 20)
//! #define POOL_OFF 0x100000u
//! #define PAGE 0x1000u
//!
//! static const uint64_t g_base[3] = { 0x8000000000ull, 0xDA00000000ull, 0xE000000000ull };
//! static uint32_t g_bump[3];
//! static uint32_t g_pool_next = POOL_OFF;
//! static uint8_t *g_mem;
//! static struct { int inited; } R = { 1 };
//! static int g_pool_rollback;
//!
//! static uint64_t heap_base(enum pvr_render_heap h) { return g_base[h]; }
//! static uint32_t *heap_bump(enum pvr_render_heap h) { return &g_bump[h]; }
//!
//! /* mem.rs bo_rollback */
//! static bool pool_bump_rollback(int heap, uint32_t hb, uint8_t *cpu, uint32_t size)
//! {
//!         uint32_t msz = ROUND_UP(size, PAGE);
//!
//!         if (!cpu || !msz || (uint64_t)hb + msz != g_bump[heap] || cpu + msz != g_mem + g_pool_next)
//!                 return false;
//!         g_bump[heap] = hb;
//!         g_pool_next -= msz;
//!         return true;
//! }
//!
//! #include "pvr_render_pool.h"
//!
//! /* pvr_render_alloc: the free list, then mem.rs bo_alloc */
//! static int pool_alloc(int heap, uint32_t size, struct pvr_gpu_bo *out)
//! {
//!         uint32_t msz = ROUND_UP(size, PAGE), co, hb;
//!
//!         if (pool_free_alloc(heap, msz, out) == 0)
//!                 return 0;
//!         co = ROUND_UP(g_pool_next, PAGE);
//!         hb = ROUND_UP(g_bump[heap], PAGE);
//!         if (msz > CARVEOUT || co > CARVEOUT - msz)
//!                 return -ENOMEM;
//!         g_pool_next = co + msz;
//!         g_bump[heap] = hb + msz;
//!         out->cpu = g_mem + co;
//!         memset(out->cpu, 0, msz);
//!         out->gpu = g_base[heap] + hb;
//!         out->heap_off = hb;
//!         return 0;
//! }
//!
//! #define MAX_BLK 4096
//! static struct { struct pvr_gpu_bo bo; uint32_t size; int heap; bool freed; } blk[MAX_BLK];
//! static unsigned nblk;
//! static unsigned nops;
//!
//! static uint32_t rng_s = 0x1234567u;
//! static uint32_t rng(void)
//! {
//!         rng_s ^= rng_s << 13;
//!         rng_s ^= rng_s >> 17;
//!         rng_s ^= rng_s << 5;
//!         return rng_s;
//! }
//!
//! static void row(char kind, uint32_t a, uint32_t b, uint32_t c, int rc, uint32_t off, uint32_t cpu)
//! {
//!         uint32_t dropped = 0, rolled = 0;
//!
//!         for (int h = 0; h <= POOL_HEAPS; h++)
//!                 dropped += g_pool_dropped_kib[h];
//!         for (int h = 0; h < POOL_HEAPS; h++)
//!                 rolled += g_pool_rolled_back_kib[h];
//!         printf("    (b'%c', [%u, %u, %u, %d, 0x%x, 0x%x, 0x%x, 0x%x, 0x%x, 0x%x, %u, %u, %u, %u, %u, %u, %u]),\n",
//!                kind, a, b, c, rc, off, cpu, g_pool_next, g_bump[0], g_bump[1], g_bump[2],
//!                g_pool_ovf_n[0], g_pool_ovf_n[1], g_pool_ovf_n[2], dropped, g_pool_double_frees,
//!                g_pool_ovf_bad, rolled);
//!         nops++;
//! }
//!
//! static void op_alloc(int heap, uint32_t size)
//! {
//!         struct pvr_gpu_bo bo = { 0 };
//!         int rc = pool_alloc(heap, size, &bo);
//!
//!         if (rc == 0) {
//!                 if (nblk >= MAX_BLK) { fprintf(stderr, "gen: MAX_BLK\n"); exit(2); }
//!                 blk[nblk].bo = bo;
//!                 blk[nblk].size = size;
//!                 blk[nblk].heap = heap;
//!                 blk[nblk].freed = false;
//!                 nblk++;
//!         }
//!         row('A', (uint32_t)heap, size, 0, rc, rc ? 0 : bo.heap_off,
//!             rc ? 0 : (uint32_t)(bo.cpu - g_mem));
//! }
//!
//! /* flags: 1 rollback on for this free, 2 no CPU mapping, 4 an address of no heap */
//! static void op_free(unsigned idx, uint32_t size, uint32_t flags)
//! {
//!         struct pvr_gpu_bo bo = blk[idx].bo;
//!
//!         if (flags & 2) bo.cpu = NULL;
//!         if (flags & 4) bo.gpu = 0x12340000ull;
//!         g_pool_rollback = (flags & 1) != 0;
//!         pvr_render_free(&bo, size);
//!         g_pool_rollback = 0;
//!         if (!(flags & 6))
//!                 blk[idx].freed = true;
//!         row('F', idx, size, flags, 0, 0, 0);
//! }
//!
//! /* overwrite the first byte of the pos-th chained range of a heap */
//! static void op_poke(int heap, unsigned pos)
//! {
//!         uint8_t *c = g_pool_ovf[heap];
//!         struct pool_ovf_hdr h;
//!
//!         for (unsigned i = 0; i < pos && c; i++) {
//!                 memcpy(&h, c, sizeof(h));
//!                 c = h.next;
//!         }
//!         if (!c) { fprintf(stderr, "gen: no chain entry %u\n", pos); exit(2); }
//!         *c = 0xEE;
//!         row('P', (uint32_t)heap, pos, 0, 0, 0, 0);
//! }
//!
//! static int live_pick(void)
//! {
//!         unsigned n = 0, k;
//!
//!         for (unsigned i = 0; i < nblk; i++) n += !blk[i].freed;
//!         if (!n) return -1;
//!         k = rng() % n;
//!         for (unsigned i = 0; i < nblk; i++)
//!                 if (!blk[i].freed && k-- == 0) return (int)i;
//!         return -1;
//! }
//!
//! int main(void)
//! {
//!         static const uint32_t sizes[] = { 0x1000, 0x1800, 0x2000, 0x3000, 0x4000, 0x9000, 0x10000, 0x21000, 0x40000 };
//!         unsigned live;
//!
//!         g_mem = calloc(1, CARVEOUT);
//!         if (!g_mem) return 2;
//!
//!         /* R: random, interleaved over the three heaps, some frees with rollback */
//!         for (int step = 0; step < 2000; step++) {
//!                 live = 0;
//!                 for (unsigned i = 0; i < nblk; i++) live += !blk[i].freed;
//!                 if (live < 120 && (live == 0 || rng() % 100 < 55)) {
//!                         op_alloc((int)(rng() % 3), sizes[rng() % (sizeof(sizes) / sizeof(sizes[0]))]);
//!                 } else {
//!                         int i = live_pick();
//!                         op_free((unsigned)i, blk[i].size, rng() % 8 == 0 ? 1 : 0);
//!                 }
//!         }
//!         /* H: more one-page holes in GENERAL than the table holds: the chain */
//!         {
//!                 unsigned first = nblk;
//!
//!                 for (int i = 0; i < 2 * 150; i++) {
//!                         op_alloc(0, PAGE);
//!                         if (nblk != first + (unsigned)i + 1) { fprintf(stderr, "gen: a hole was refused\n"); return 2; }
//!                 }
//!                 for (int i = 0; i < 150; i++) op_free(first + 2 * i, PAGE, 0);
//!                 /* D: double frees, newest (on the chain) and oldest (in the table),
//!                  * and a free larger than the block that overlaps a free neighbour */
//!                 op_free(first + 2 * 149, PAGE, 0);
//!                 op_free(first, PAGE, 0);
//!                 op_free(first + 1, 3 * PAGE, 0);
//!                 /* X: a chain header overwritten while free, then allocations that
//!                  * walk the chain */
//!                 op_poke(0, 1);
//!                 for (int i = 0; i < 20; i++) op_alloc(0, PAGE);
//!                 op_alloc(0, 2 * PAGE);
//!         }
//!         /* O: frees the pool cannot take back */
//!         op_free(0, PAGE, 2);
//!         op_free(1, 2 * PAGE, 4);
//!         /* Z: a request past the carveout, and one the bump serves */
//!         op_alloc(0, CARVEOUT);
//!         op_alloc(2, 0x30000);
//!         /* F: every live block freed, rollback on for every third, then large
//!          * requests from what merged */
//!         for (unsigned i = 0, k = 0; i < nblk; i++)
//!                 if (!blk[i].freed) op_free(i, blk[i].size, (k++ % 3) == 0 ? 1 : 0);
//!         op_alloc(0, 0x100000);
//!         op_alloc(1, 0x80000);
//!         op_alloc(2, 0x80000);
//!         fprintf(stderr, "gen: %u operations, %u blocks, chain peak %u/%u/%u, slots peak %u/%u/%u, "
//!                 "dropped %u KiB, double frees %u, bad headers %u\n", nops, nblk,
//!                 g_pool_ovf_peak[0], g_pool_ovf_peak[1], g_pool_ovf_peak[2],
//!                 g_pool_slots_peak[0], g_pool_slots_peak[1], g_pool_slots_peak[2],
//!                 g_pool_dropped_kib[0] + g_pool_dropped_kib[1] + g_pool_dropped_kib[2] + g_pool_dropped_kib[3],
//!                 g_pool_double_frees, g_pool_ovf_bad);
//!         return 0;
//! }
//! ```

